function drawPlaying() {
  drawStars();
  drawHUD();

  // Tractor beams behind enemies
  for (const e of G.enemies) {
    if (e.state === 'tractor' && e.tractorTimer >= 0.8) {
      const phase = e.tractorPhase;
      const halfW = 8 + phase * 14;

      ctx.fillStyle = 'rgba(80,180,255,0.25)';
      ctx.beginPath();
      ctx.moveTo(e.x - 6, e.y + 4);
      ctx.lineTo(e.x + 6, e.y + 4);
      ctx.lineTo(e.x + halfW, H);
      ctx.lineTo(e.x - halfW, H);
      ctx.closePath();
      ctx.fill();

      ctx.fillStyle = 'rgba(150,220,255,0.5)';
      for (let i = 0; i < 4; i++) {
        const yy = e.y + 10 + ((phase * 40 + i * 20) % (H - e.y - 10));
        const w = 6 + (yy - e.y) * 0.28;
        ctx.fillRect(e.x - w / 2, yy, w, 2);
      }
    }
  }

  // Enemies
  for (const e of G.enemies) {
    if (e.dead) continue;
    if (e.state === 'challenge' && e.challengeT < e.challengeDelay) continue;

    if (e.type === 'zako') drawZako(e.x, e.y, e.wingPhase);
    else if (e.type === 'goei') drawGoei(e.x, e.y, e.wingPhase);
    else if (e.type === 'boss') drawBoss(e.x, e.y, e.wingPhase, e.bossHit);
  }

  // Captured fighters
  for (const cf of G.capturedFighters) {
    if (!cf.dead) drawPlayerShip(cf.x, cf.y, false, true);
  }

  // Freed ships flying down
  for (const fs of G.freedShips) {
    drawPlayerShip(fs.x, fs.y, false, true);
  }

  // Bullets
  ctx.fillStyle = '#ffffff';
  for (const b of G.playerBullets) {
    ctx.fillRect(Math.floor(b.x), Math.floor(b.y), b.w, b.h);
  }

  ctx.fillStyle = '#ffcc00';
  for (const b of G.enemyBullets) {
    ctx.fillRect(Math.floor(b.x), Math.floor(b.y), b.w, b.h);
  }

  // Player
  if (G.player && G.player.alive) {
    drawPlayerShip(G.player.x, G.player.y, G.player.dual, false);
  } else if (G.player && G.player.respawnTimer > 0) {
    drawPixelText('READY', W / 2, H - 50, '#ffffff', 10);
  }

  // Explosions
  for (const ex of G.explosions) {
    drawExplosion(ex);
  }

  if (G.paused) {
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(0, 0, W, H);
    drawPixelText('PAUSED', W / 2, H / 2, '#ffffff', 16);
  }
}

function drawChallengeResults() {
  drawStars();
  drawHUD();
  drawPixelText('CHALLENGING STAGE', W / 2, 80, '#ffcc00', 12);
  drawPixelText('NUMBER OF HITS', W / 2, 120, '#ffffff', 10);
  drawPixelText(String(G.challengeHits), W / 2, 140, '#ffffff', 16);

  if (G.challengePerfect) {
    drawPixelText('PERFECT!', W / 2, 170, '#ffcc00', 14);
  }
  drawPixelText('BONUS ' + G.challengeBonus, W / 2, 200, '#66ccff', 10);
}

function drawGameOver() {
  drawStars();
  drawHUD();
  drawPixelText('GAME OVER', W / 2, 80, '#ffffff', 16);

  const ratio = G.shotsFired > 0 ? (G.hits / G.shotsFired * 100) : 0;

  drawPixelText('SHOTS FIRED', 70, 130, '#ffffff', 8);
  drawPixelText(String(G.shotsFired), 170, 130, '#ffffff', 8);
  drawPixelText('NUMBER OF HITS', 70, 150, '#ffffff', 8);
  drawPixelText(String(G.hits), 170, 150, '#ffffff', 8);
  drawPixelText('HIT-MISS RATIO', 70, 170, '#ffffff', 8);
  drawPixelText(ratio.toFixed(1) + '%', 170, 170, '#ffffff', 8);

  drawPixelText('PRESS ENTER', W / 2, 220, '#ffffff', 8);
}

/* =========================================================
   INPUT
   ========================================================= */
const keys = {};

window.addEventListener('keydown', (e) => {
  ensureAudio();
  if (e.repeat) return;
  keys[e.code] = true;

  if (e.code === 'Enter') {
    if (G.mode === 'title') {
      G.score = 0;
      G.reserveShips = 2;
      G.nextExtraScore = 20000;
      G.shotsFired = 0;
      G.hits = 0;
      G.completedStages = [];
      G.player = null;
      startStage(1);
    } else if (G.mode === 'gameOver') {
      G.mode = 'title';
      G.player = null;
    }
  }

  if (e.code === 'Space') {
    e.preventDefault();
    firePlayerShot();
  }

  if (e.code === 'KeyP') {
    G.paused = !G.paused;
  }

  if (e.code === 'KeyM') {
    muted = !muted;
  }
});

window.addEventListener('keyup', (e) => {
  keys[e.code] = false;
});

/* =========================================================
   FIXED-TIMESTEP LOOP
   ========================================================= */
const STEP = 1 / 60;
let lastTime = performance.now();
let accumulator = 0;

function loop(now) {
  const dt = Math.min(0.1, (now - lastTime) / 1000);
  lastTime = now;
  accumulator += dt;

  while (accumulator >= STEP) {
    updateGame(STEP);
    accumulator -= STEP;
  }

  ctx.clearRect(0, 0, W, H);

  if (G.mode === 'title') drawTitleScreen();
  else if (G.mode === 'stageIntro') drawStageIntro();
  else if (G.mode === 'playing') drawPlaying();
  else if (G.mode === 'challengeResults') drawChallengeResults();
  else if (G.mode === 'gameOver') drawGameOver();

  requestAnimationFrame(loop);
}

requestAnimationFrame(loop);
</script>
</body>
</html>
```

Things not implemented exactly as spec:
- The title screen is a simplified text-based attract screen rather than a full arcade attract animation.
- Enemy entry paths are simplified curved Bezier groups rather than exact arcade entry formations.
- Boss Galaga escort behavior is simplified; escorts follow the boss and return after the boss is destroyed.
- Tractor-beam capture of a dual fighter is handled as losing one half, but the remaining ship stays in place rather than being repositioned to the exact surviving half.
- Stage badges are shown only for completed milestone stages (1, 5, 10, 20, 30, 50), not for every possible arcade badge state.
- Audio is synthesized approximations, not exact arcade sound reproductions.
